<script setup lang="ts">
// the Dungeon Master asks the table for dice
import { computed, ref } from 'vue'
import { app, gs, hands, rollExpr, rollSecret, stageThrow } from '../session'
import { ABILITIES, ABILITY_NAME, SKILL_IDS, SKILL_NAME } from '../rules/base'
const heroes = computed(() => Object.entries(gs.value?.chars ?? {}).filter(([, h]) => !h.dead)); const who = ref<string[]>([]), kind = ref<'check' | 'save' | 'dice'>('check'), skill = ref('perception'), ab = ref('dex'), dc = ref(13), adv = ref('none'), secret = ref(false), why = ref(''), dice = ref('1d100'), roll = ref(''); const tog = (id: string) => { const i = who.value.indexOf(id); i >= 0 ? who.value.splice(i, 1) : who.value.push(id) }; const DC = [[5, 'Easy'], [10, 'Plain'], [13, 'Fair'], [15, 'Hard'], [18, 'Harder'], [20, 'Very hard']] as const
const ask = () => { const L = who.value.length ? who.value : ['party']; for (const w of L) { const q = { who: w, why: why.value || undefined }; if (kind.value === 'check') hands('ask_check', { ...q, skill: skill.value, dc: dc.value, advantage: adv.value, secret: secret.value }); else if (kind.value === 'save') hands('ask_save', { ...q, ability: ab.value, dc: dc.value, advantage: adv.value, secret: secret.value }); else hands('ask_dice', { ...q, dice: dice.value }) } }; const calls = computed(() => gs.value?.calls ?? []); const done = computed(() => app.log.filter(e => e.total !== undefined && e.src && gs.value?.chars[e.src]).slice(-6).reverse())
</script>
<template><div><span class="cap">Ask for a roll</span><p v-if="!heroes.length" class="muted">No heroes at the table yet.</p><div class="chips"><button class="chip s" :class="{ on: !who.length }" @click="who = []">Everyone</button><button v-for="[id, h] in heroes" :key="id" class="chip s" :class="{ on: who.includes(id) }" @click="tog(id)">{{ h.name }}</button></div><div class="chips" style="margin-top:8px"><button class="chip s" :class="{ on: kind === 'check' }" @click="kind = 'check'">Check</button><button class="chip s" :class="{ on: kind === 'save' }" @click="kind = 'save'">Saving throw</button><button class="chip s" :class="{ on: kind === 'dice' }" @click="kind = 'dice'">Any dice</button></div>
  <select v-if="kind === 'check'" v-model="skill" class="field" style="margin-top:8px" aria-label="Skill or ability"><option v-for="s in SKILL_IDS" :key="s" :value="s">{{ SKILL_NAME[s] }}</option><option v-for="a in ABILITIES" :key="a" :value="a">{{ ABILITY_NAME[a] }}</option></select><select v-if="kind === 'save'" v-model="ab" class="field" style="margin-top:8px" aria-label="Ability"><option v-for="a in ABILITIES" :key="a" :value="a">{{ ABILITY_NAME[a] }}</option></select><input v-if="kind === 'dice'" v-model="dice" class="field" style="margin-top:8px" aria-label="Which dice" placeholder="1d100">
  <template v-if="kind !== 'dice'"><div class="chips" style="margin-top:8px"><button v-for="d in DC" :key="d[0]" class="chip s" :class="{ on: dc === d[0] }" v-tip="d[1]" @click="dc = d[0]">{{ d[0] }}</button><input v-model.number="dc" type="number" min="1" max="30" class="field" style="width:74px" aria-label="Difficulty"></div><div class="chips" style="margin-top:8px"><button v-for="a in ['none', 'advantage', 'disadvantage']" :key="a" class="chip s" :class="{ on: adv === a }" @click="adv = a">{{ a === 'none' ? 'Straight' : a === 'advantage' ? 'Advantage' : 'Disadvantage' }}</button><button class="chip s" :class="{ on: secret }" @click="secret = !secret">Only I see it</button></div></template><input v-model="why" class="field" style="margin-top:8px" :placeholder="kind === 'save' ? 'Against what?' : 'To do what?'" aria-label="Why" maxlength="80"><button class="btn primary big wide" style="margin-top:10px" :disabled="!heroes.length" @click="ask">Ask</button>
  <template v-if="calls.length"><span class="cap">The table is throwing</span><div v-for="c in calls" :key="c.id" class="c"><b>{{ gs?.chars[c.who]?.name }}</b><span class="grow">{{ c.groups[0].label }}</span><button class="btn sm" @click="stageThrow(c.id)">Throw for them</button></div></template><template v-if="done.length"><span class="cap">Last throws</span><div v-for="e in done" :key="e.id" class="c"><b>{{ e.who }}</b><span class="grow">{{ e.label }}{{ e.secret ? ', secret' : '' }}<template v-if="e.dc && e.t !== 'roll'"> {{ e.ok ? 'made' : 'missed' }}</template></span><strong>{{ e.total }}</strong></div></template>
  <span class="cap">Your own dice</span><div class="row" style="gap:2px"><button v-for="d in [4, 6, 8, 10, 12, 20, 100]" :key="d" class="btn sm grow" style="padding:0" @click="rollExpr('d' + d)">{{ d }}</button></div><form class="row" style="margin-top:6px" @submit.prevent="rollExpr(roll)"><input v-model="roll" class="field" placeholder="2d6+3, d20 adv" aria-label="Dice"><button class="btn" type="button" @click="rollSecret(roll || 'd20')">Secret</button></form></div></template>
<style scoped>.c{display:flex;gap:9px;align-items:center;padding:5px 0;border-bottom:1px solid var(--line);font-size:16px}.c b{font-weight:600}.c span{color:var(--tx2);min-width:0}strong{font:800 25px/1 var(--serif)}</style>
